import {
    Table,
    ConditionsColumn,
    DecimalColumn,
    StringColumn,
    ReferenceColumn,
    DurationColumn,
    GuidColumn,
    GenericColumn,
} from '@servicenow/sdk/core'

export const sc_cat_item_delivery_task = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_metadata',
    extensible: true,
    label: 'Execution Plan Task',
    name: 'sc_cat_item_delivery_task',
    schema: {
        condition: ConditionsColumn({
            attributes: {
                remoteDependent: 'delivery_plan.task_table',
            },
            label: 'Condition',
        }),
        order: DecimalColumn({
            default: '100',
            label: [
                {
                    hint: 'The order a task is executed. Blank means the task does not depend on order',
                    label: 'Order',
                    plural: 'Orders',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        short_description: StringColumn({
            label: 'Short description',
            maxLength: 120,
        }),
        delivery_plan: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Execution plan for this task',
                    label: 'Delivery plan',
                    plural: 'Delivery plans',
                    language: 'en',
                },
            ],
            referenceTable: 'sc_cat_item_delivery_plan',
            referenceFloats: true,
        }),
        sla: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'SLA',
            referenceTable: 'sysrule_escalate',
            referenceQual: 'table=sc_task',
        }),
        delivery_time: DurationColumn({
            label: [
                {
                    hint: 'Time it takes to complete this task',
                    label: 'Delivery time',
                    plural: 'Delivery times',
                    language: 'en',
                },
            ],
            maxLength: 40,
        }),
        assigned_to: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'The default assignment when a ticket is created from this task',
                    label: 'Assigned to',
                    plural: 'Assigned to',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        generation_script: GenericColumn({
            columnType: 'script_plain',
            label: 'Generation script',
            maxLength: 4000,
        }),
        work_notes: StringColumn({
            label: [
                {
                    hint: 'Private work notes for this delivery task',
                    label: 'Work notes',
                    plural: 'Work notes',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
            textIndex: true,
        }),
        instructions: StringColumn({
            label: [
                {
                    hint: "Instructions will be copied over to the resulting ticket's description",
                    label: 'Instructions',
                    plural: 'Instructions',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
            textIndex: true,
        }),
        group: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Group assigned to fulfill, or complete this task',
                    label: 'Fulfillment group',
                    plural: 'Fulfillment groups',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user_group',
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),
        condition_script: GenericColumn({
            columnType: 'script_plain',
            label: 'Condition script',
            maxLength: 4000,
        }),
    },
})
